<script setup lang="ts">
import {onMounted,ref} from 'vue';import {adjustInventory,getInventory,getStockLedger,getVariants,getWarehouses,type Inventory,type StockLedgerEntry,type Variant,type Warehouse} from '@/services/business';import {useAuthStore} from '@/stores/auth'
const auth=useAuthStore(),items=ref<Inventory[]>([]),warehouses=ref<Warehouse[]>([]),variants=ref<Variant[]>([]),search=ref(''),warehouseId=ref(''),error=ref(''),loading=ref(false),show=ref(false),saving=ref(false);const form=ref({warehouseId:'',variantId:'',quantityDelta:0,reason:''})
const ledger=ref<StockLedgerEntry[]>([]),ledgerType=ref('')
async function load(){loading.value=true;error.value='';try{const [inventory,transactions]=await Promise.all([getInventory(search.value,warehouseId.value||undefined),getStockLedger(warehouseId.value||undefined,undefined,ledgerType.value)]);items.value=inventory.items;ledger.value=transactions.items}catch{error.value='Không thể tải tồn kho hoặc stock ledger.'}finally{loading.value=false}}
async function submit(){saving.value=true;error.value='';try{await adjustInventory(form.value);show.value=false;form.value={warehouseId:'',variantId:'',quantityDelta:0,reason:''};await load()}catch{error.value='Điều chỉnh thất bại. Tồn kho không được âm và lý do là bắt buộc.'}finally{saving.value=false}}
onMounted(async()=>{warehouses.value=await getWarehouses();if(auth.hasPermission('inventory.adjust'))variants.value=await getVariants();await load()})
</script>
<template><section class="p-6 lg:p-8"><div class="flex flex-wrap justify-between gap-4"><div><p class="text-sm font-semibold text-cyan-700">Quản lý kho</p><h2 class="text-3xl font-bold">Tồn kho</h2></div><button v-if="auth.hasPermission('inventory.adjust')" class="rounded-lg bg-cyan-600 px-4 py-2 font-semibold text-white" @click="show=!show">Điều chỉnh</button></div><form class="mt-5 flex flex-wrap gap-2" @submit.prevent="load"><select v-model="warehouseId" class="rounded-lg border px-3 py-2"><option value="">Tất cả kho</option><option v-for="w in warehouses" :key="w.id" :value="w.id">{{w.name}}</option></select><input v-model.trim="search" placeholder="SKU hoặc sản phẩm…" class="rounded-lg border px-3 py-2"><select v-model="ledgerType" class="rounded-lg border px-3 py-2"><option value="">Mọi giao dịch</option><option v-for="type in ['PURCHASE_RECEIPT','SALE','RETURN','TRANSFER_OUT','TRANSFER_IN','ADJUSTMENT','STOCKTAKE']" :key="type">{{type}}</option></select><button class="rounded-lg bg-slate-900 px-4 py-2 text-white">Lọc</button></form><form v-if="show" class="mt-5 grid gap-4 rounded-xl border bg-white p-5 md:grid-cols-2" @submit.prevent="submit"><select v-model="form.warehouseId" required class="rounded-lg border px-3 py-2"><option value="" disabled>Chọn kho</option><option v-for="w in warehouses" :key="w.id" :value="w.id">{{w.name}}</option></select><select v-model="form.variantId" required class="rounded-lg border px-3 py-2"><option value="" disabled>Chọn SKU</option><option v-for="v in variants" :key="v.id" :value="v.id">{{v.sku}} — {{v.productName}}</option></select><input v-model.number="form.quantityDelta" required type="number" step="0.0001" placeholder="Số lượng +/-" class="rounded-lg border px-3 py-2"><input v-model.trim="form.reason" required minlength="3" placeholder="Lý do" class="rounded-lg border px-3 py-2"><button :disabled="saving" class="rounded-lg bg-slate-900 px-4 py-2 text-white md:col-span-2">{{saving?'Đang lưu…':'Xác nhận điều chỉnh'}}</button></form><p v-if="error" class="mt-5 rounded-lg bg-red-50 p-4 text-red-800">{{error}}</p><div v-if="!loading" class="mt-6 overflow-x-auto rounded-xl border bg-white"><table class="w-full text-left text-sm"><thead class="bg-slate-50"><tr><th class="p-4">Kho</th><th class="p-4">SKU</th><th class="p-4">Sản phẩm</th><th class="p-4">Hiện có</th><th class="p-4">Đã giữ</th><th class="p-4">Khả dụng</th></tr></thead><tbody class="divide-y"><tr v-for="i in items" :key="i.id"><td class="p-4">{{i.warehouseName}}</td><td class="p-4 font-mono">{{i.sku}}</td><td class="p-4">{{i.productName}}</td><td class="p-4">{{i.quantity}}</td><td class="p-4">{{i.reservedQuantity}}</td><td class="p-4 font-semibold">{{i.availableQuantity}}</td></tr></tbody></table></div><div v-if="!loading" class="mt-6 overflow-x-auto rounded-xl border bg-white"><div class="border-b p-4"><h3 class="font-bold">Nhật ký kho bất biến</h3><p class="text-xs text-slate-500">100 dòng gần nhất theo bộ lọc kho và loại giao dịch.</p></div><table class="w-full text-left text-sm"><thead class="bg-slate-50"><tr><th class="p-4">Thời gian / ref</th><th class="p-4">Loại</th><th class="p-4">Kho / SKU</th><th class="p-4">Thay đổi</th><th class="p-4">Trước → sau</th><th class="p-4">Nguồn / lý do</th></tr></thead><tbody class="divide-y"><tr v-for="entry in ledger" :key="entry.transactionId+entry.variantId"><td class="p-4">{{new Date(entry.occurredAt).toLocaleString()}}<p class="font-mono text-xs">{{entry.reference}}</p></td><td class="p-4 font-semibold"><StatusBadge :value="entry.type" /></td><td class="p-4">{{entry.warehouseName}}<p class="font-mono text-xs">{{entry.sku}}</p></td><td class="p-4" :class="entry.quantityDelta>0?'text-emerald-700':'text-red-700'">{{entry.quantityDelta>0?'+':''}}{{entry.quantityDelta}}</td><td class="p-4">{{entry.quantityBefore}} → {{entry.quantityAfter}}</td><td class="p-4">{{entry.sourceType||'thủ công'}}<p class="text-xs text-slate-500">{{entry.reason}}</p></td></tr><tr v-if="!ledger.length"><td colspan="6" class="p-8 text-center text-slate-400">Chưa có giao dịch kho.</td></tr></tbody></table></div></section></template>
